// Draft Check: applies the email template's HARD RULES and Alex's scrub list to
// the drafted email. Violations send the draft back for one redraft; anything
// still failing, or needing Alex's input, is flagged in Abel's Missive note.
const ATTEMPT = 1;
const NUMBERS = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };

// Alex's scrub list (skills/alex-profile/references/ai-scrubbing.md in alex-os).
const BANNED = [
  'really', 'just', 'very', 'actually', 'basically', 'literally', 'thing', 'things',
  "i'd argue", 'sort of', 'kind of', 'amazing', 'huge', 'excited to', 'thrilled',
  'i hope this finds you', 'hope you are well', 'wanted to reach out', 'just following up',
  'circle back', 'touch base', 'great connecting', 'it was great', 'looking forward to hearing',
  'feels like', 'i really like', 'delighted', 'synergy', 'leverage', 'sounding board',
];

function body(content) {
  const lines = String(content || '').trim().split(/\r?\n/);
  // Drop the greeting ("Brian,") and the sign-off ("Alex", "Best,").
  while (lines.length && /^\s*$/.test(lines[0])) lines.shift();
  if (lines.length && /^[^.!?]{1,40},\s*$/.test(lines[0])) lines.shift();
  while (lines.length && (/^\s*$/.test(lines[lines.length - 1]) || /^\s*(alex|best,?|thanks,?|alex brownstein)\s*$/i.test(lines[lines.length - 1]))) lines.pop();
  return lines.join('\n');
}

function sentenceLimit(template) {
  const m = String(template || '').match(/\b(\w+)\s+to\s+(\w+)\s+sentences\b/i);
  if (!m) return null;
  const max = NUMBERS[m[2].toLowerCase()] || Number(m[2]);
  return Number.isFinite(max) ? max : null;
}

function templateBanned(template) {
  const line = String(template || '').split(/\r?\n/).find(l => /banned:/i.test(l)) || '';
  return [...line.matchAll(/["“]([^"”]+)["”]/g)].map(m => m[1].replace(/[.,]$/, '').toLowerCase());
}

const template = $('Get Template').item.json.markdown_description || '';
const content = String($json.output?.content || '');
const text = body(content);
const lower = text.toLowerCase();
const violations = [];
const needs_input = [];

const max = sentenceLimit(template);
const sentences = text.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(s => /[a-z]/i.test(s));
const words = text.split(/\s+/).filter(Boolean).length;
// Short closers ("No ask here.", "Glad we connected.") don't count toward the limit.
const counted = sentences.filter(s => s.split(/\s+/).length > 4).length;
if (max && counted > max) violations.push(`${counted} sentences; the template allows ${max}`);
if (max && words > max * 18) violations.push(`${words} words; keep it under ${max * 18}`);
const long = sentences.filter(s => s.split(/\s+/).length > 30).length;
if (long) violations.push(`${long} sentence(s) over 30 words`);
if (/[—–]/.test(text)) violations.push('uses a dash (— or –)');
if (/;/.test(text)) violations.push('uses a semicolon');
for (const phrase of [...new Set([...BANNED, ...templateBanned(template)])]) {
  const re = new RegExp(`(^|[^a-z'])${phrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z]|$)`, 'i');
  if (re.test(lower)) violations.push(`banned phrase "${phrase}"`);
}
// Word ceiling from router SOP 868fkyv39 §B, keyed on the template Get Template fetched.
const CEILINGS = {
  '868fkypqb': { name: 'Client Email Template', ceiling: 200 },
  '868kwthkm': { name: 'Prospect Discovery Recap Email Template', ceiling: 200 },
  '868kwth55': { name: 'Networking Thank You', ceiling: 100 },
  '868kwthvd': { name: 'Intro & Referral Email Template', ceiling: 100 },
  '868fkyrja': { name: 'Vendor / Partner Email Template', ceiling: 150 },
  '868fkyjfj': { name: 'Internal Email Template', ceiling: null },
};
const ceilingRow = CEILINGS[String($('Get Template').item.json.id || '')];
const ceiling = ceilingRow ? ceilingRow.ceiling : null;
if (ceiling && words > ceiling) violations.push(`${words} words; the route's ceiling is ${ceiling}`);
if (/\[[^\]]+\]/.test(text)) needs_input.push('has a [placeholder] for Alex to fill');
if (!text.trim()) needs_input.push('no draft body');

return { json: { ...$json, check: { attempt: ATTEMPT, sentences: sentences.length, words, violations, needs_input } } };

