    out.hitl_message = (out.hitl_message ? out.hitl_message + '\n\n' : '') +
      'Abel picked a template that does not exist ("' + got + '"). Reply with the template to use: ' +
      Object.values(TEMPLATES).map(t => t.name).join(', ') + '.';
    out.route_guard = 'unknown template: ' + got;
  }
}
return { json: { ...$json, output: out } };
